"""Public-evidence conventional study controls plus owner-only world construction.

The conventional predictor is a predeclared local interpolator, not an investigator
solution or physical model. The selector chooses experiments with the public action
interface. Owner worlds and targets must never enter the investigator filesystem.
No functions here invoke a provider, execute a laboratory, or update weights.
"""

from __future__ import annotations

import copy
import hashlib
import json
import math
from collections import defaultdict

BASELINE_VERSION = "conventional-clustered-study-v1"
BASELINE_ASSUMPTIONS = {
    "method": "piecewise_linear_actual_temperature_cluster_means",
    "pressure_tolerance_mpa": 2.0,
    "tolerance_rationale": "Declared conditional approximation for small pressure readback deviations; not an RPI acceptance limit or established pressure insensitivity.",
    "other_process_context": "exact known lot, origin, route, stage, dwell, ramp and geometry",
    "temperature": "actual readbacks; no extrapolation beyond observed temperatures",
    "dependence": "connected components sharing any preparation or cycle identifier",
    "cluster_uncertainty": "descriptive between-component mean SE at exact temperature nodes only; at least three components",
    "predictive_uncertainty": "not estimated; no interval or noninferiority probability",
    "scientific_scope": "conditional computational comparison, not material validation",
}
_UNITS = {"density_g_cm3": "g/cm^3", "grain_size_nm": "nm", "grain_d90_nm": "nm",
          "coarse_number_fraction": "1", "porosity_area_fraction": "1"}
_CONTEXT = ("route", "process_stage", "post_treatment", "hold_time_s",
            "heating_rate_c_min", "mass_g", "diameter_mm")
_GRAIN = {"grain_size_nm", "grain_d90_nm", "coarse_number_fraction"}


def _finite(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _stage(value):
    return "as_sintered" if value in {"initial_sps", "as_sps", "as_sintered"} else value


def _empty(quantity, reason, exclusions=None):
    return {"mean": None, "sd": None, "unit": _UNITS[quantity], "status": "unsupported",
            "reason": reason, "uncertainty_status": "not_estimated",
            "exclusions": exclusions or []}


def _components(rows):
    """Transitive manufacturing dependence; a fresh wrapper ID is not a repeat."""
    parent = list(range(len(rows)))

    def root(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    seen = {}
    for index, row in enumerate(rows):
        for field in ("preparation_id", "cycle_id"):
            identifier = row.get(field)
            if identifier is None:
                # Unknown genealogy joins all unknowns, never grants independence.
                identifier = "__unknown__"
            key = (field, identifier)
            if key in seen:
                parent[root(index)] = root(seen[key])
            else:
                seen[key] = index
    groups = defaultdict(list)
    for index, row in enumerate(rows):
        groups[root(index)].append(row)
    return list(groups.values())


def _eligible(condition, request, evidence, quantity):
    accepted, exclusions = [], []
    context = condition.get("measurement_context", {}).get(quantity, {})
    candidates = defaultdict(list)
    for row in evidence:
        if row.get("quantity") == quantity:
            candidates[row.get("evidence_id")].append(row)
    for identifier, duplicates in candidates.items():
        row = duplicates[0]
        actual = row.get("delivered_conditions") or {}
        reason = None
        if not identifier or any(other != row for other in duplicates[1:]):
            reason = "missing_or_conflicting_evidence_identity"
        elif row.get("superseded") or row.get("status") not in {"accepted", "conditional_synthetic", "derived"}:
            reason = "unavailable_or_superseded"
        elif row.get("status") == "derived" and not row.get("quality_review"):
            reason = "unreviewed_derivation"
        elif row.get("quality_review") is not None and (
            not isinstance(row["quality_review"], dict)
            or row["quality_review"].get("decision") != "accepted"
            or not row["quality_review"].get("reviewer")
            or not row["quality_review"].get("rationale")
        ):
            reason = "quality_review_not_accepted"
        elif not row.get("released_at"):
            reason = "unreleased"
        elif row.get("origin") != request.get("origin") or row.get("lot_id") != request.get("lot_id"):
            reason = "wrong_origin_or_lot"
        elif row.get("unit") != _UNITS[quantity] or not _finite(row.get("value")):
            reason = "invalid_value_or_unit"
        elif (_UNITS[quantity] == "1" and not 0 <= row["value"] <= 1) or (_UNITS[quantity] != "1" and row["value"] <= 0):
            reason = "outside_quantity_domain"
        elif quantity in _GRAIN and row.get("resolved_grain_boundaries") is not True:
            reason = "unresolved_grain_boundaries"
        elif not row.get("specimen_id") or not (row.get("measurement_id") or row.get("observation_id")):
            reason = "missing_specimen_or_measurement_identity"
        elif row.get("statistical_unit") != "specimen":
            reason = "not_a_specimen_descriptor"
        elif actual.get("origin", request.get("origin")) != request.get("origin"):
            reason = "delivered_origin_conflict"
        elif (row.get("actual_genealogy") or {}).get("lot_id", request["lot_id"]) != request["lot_id"]:
            reason = "actual_genealogy_lot_conflict"
        elif actual.get("lot_id", row.get("lot_id")) != request["lot_id"]:
            reason = "delivered_lot_conflict"
        elif any(actual.get(k) is None or condition.get(k) is None or
                 (_stage(actual[k]) != _stage(condition[k]) if k == "process_stage" else actual[k] != condition[k])
                 for k in _CONTEXT):
            reason = "unknown_or_different_process_context"
        elif _stage(row.get("measurement_stage", row.get("process_stage"))) != _stage(condition.get("process_stage")):
            reason = "unknown_or_different_measurement_endpoint"
        elif condition.get("die_material") is not None and actual.get("die_material") != condition["die_material"]:
            reason = "unknown_or_different_tooling"
        elif not _finite(actual.get("pressure_mpa")) or not _finite(condition.get("pressure_mpa")) or abs(actual["pressure_mpa"] - condition["pressure_mpa"]) > BASELINE_ASSUMPTIONS["pressure_tolerance_mpa"]:
            reason = "pressure_outside_declared_tolerance"
        elif not _finite(actual.get("temperature_c")):
            reason = "unknown_delivered_temperature"
        elif not all(context.get(k) and row.get(k) == context[k] for k in ("method", "measurement_population", "measurement_statistic")):
            reason = "unknown_or_different_measurement_context"
        elif quantity == "coarse_number_fraction" and (not _finite(context.get("coarse_threshold_nm")) or row.get("coarse_threshold_nm") != context["coarse_threshold_nm"]):
            reason = "unknown_or_different_coarse_threshold"
        elif request.get("origin") == "physical" and quantity in _GRAIN and not all(context.get(k) and row.get(k) == context[k] for k in ("feature_definition", "weighting", "sampling_plan")):
            reason = "unknown_physical_grain_definition"
        elif request.get("origin") == "physical" and quantity == "porosity_area_fraction" and not all(context.get(k) and row.get(k) == context[k] for k in ("weighting", "sampling_plan")):
            reason = "unknown_physical_porosity_sampling"
        if reason:
            exclusions.append({"evidence_id": identifier, "reason": reason})
        else:
            accepted.append(row)
    by_specimen = defaultdict(list)
    by_measurement = defaultdict(list)
    for row in accepted:
        by_specimen[row["specimen_id"]].append(row)
        by_measurement[row.get("measurement_id") or row["observation_id"]].append(row)
    conflicting = set()
    comparison_keys = ("specimen_id", "value", "delivered_conditions", "preparation_id", "cycle_id")
    for rows in [*by_specimen.values(), *by_measurement.values()]:
        if any(any(row.get(k) != rows[0].get(k) for k in comparison_keys) for row in rows[1:]):
            conflicting.update(row["evidence_id"] for row in rows)
    deduplicated = []
    for rows in by_specimen.values():
        if any(row["evidence_id"] in conflicting for row in rows):
            exclusions.extend({"evidence_id": row["evidence_id"], "reason": "conflicting_specimen_or_measurement_descriptor"} for row in rows)
        else:
            deduplicated.append(rows[0])
            exclusions.extend({"evidence_id": row["evidence_id"], "reason": "duplicate_specimen_descriptor"} for row in rows[1:])
    return deduplicated, exclusions


def forecast(payload):
    """Predeclared conventional forecast from the exact public evidence snapshot."""
    request, evidence = payload["request"], payload.get("evidence", [])
    predictions = []
    for specimen in request["specimens"]:
        condition = specimen["conditions"]
        output = {"specimen_id": specimen["specimen_id"]}
        quantities = specimen.get("measurements", request.get("measurements", ["density_g_cm3", "grain_size_nm"]))
        for quantity, unit in _UNITS.items():
            if quantity not in quantities:
                continue
            if request.get("origin") not in {"synthetic", "physical"}:
                output[quantity] = _empty(quantity, "Unknown origin")
                continue
            rows, exclusions = _eligible(condition, request, evidence, quantity)
            target = condition.get("temperature_c")
            if not rows or not _finite(target):
                output[quantity] = _empty(quantity, "No eligible evidence or target", exclusions)
                continue
            groups = _components(rows)
            group_index = {r["specimen_id"]: index for index, group in enumerate(groups) for r in group}
            cells = defaultdict(lambda: defaultdict(list))
            for row in rows:
                cells[row["delivered_conditions"]["temperature_c"]][group_index[row["specimen_id"]]].append(row)
            temperatures = sorted(cells)
            if not temperatures[0] <= target <= temperatures[-1]:
                output[quantity] = _empty(quantity, "Outside observed temperature support", exclusions)
                continue
            summaries = {}
            for temperature, cell in cells.items():
                means = [sum(r["value"] for r in members) / len(members) for members in cell.values()]
                mean = sum(means) / len(means)
                known = all(r.get("preparation_id") and r.get("cycle_id") for members in cell.values() for r in members)
                # If a component spans temperatures, the contrast is dependent.
                se = math.sqrt(sum((m - mean) ** 2 for m in means) / (len(means) * (len(means) - 1))) if len(means) >= 3 and known else None
                summaries[temperature] = {"mean": mean, "n_components": len(means), "descriptive_component_mean_se": se,
                                          "component_ids": sorted(cell), "genealogy_known": known}
            lower = max(t for t in temperatures if t <= target)
            upper = min(t for t in temperatures if t >= target)
            weight = 0.0 if lower == upper else (target - lower) / (upper - lower)
            low, high = summaries[lower], summaries[upper]
            mean = (1 - weight) * low["mean"] + weight * high["mean"]
            mean_se = low["descriptive_component_mean_se"] if lower == upper else None
            if lower != upper and not set(low["component_ids"]) & set(high["component_ids"]) and all(x["descriptive_component_mean_se"] is not None for x in (low, high)):
                mean_se = math.hypot((1 - weight) * low["descriptive_component_mean_se"], weight * high["descriptive_component_mean_se"])
            output[quantity] = {"mean": mean, "sd": None, "unit": unit,
                "status": "conditional_local_descriptive_fit", "measurement_stage": condition["process_stage"],
                "measurement_context": copy.deepcopy(condition["measurement_context"][quantity]),
                **({"coarse_threshold_nm": condition["measurement_context"][quantity]["coarse_threshold_nm"]} if quantity == "coarse_number_fraction" else {}),
                "method": BASELINE_ASSUMPTIONS["method"], "evidence_ids": [r["evidence_id"] for r in rows],
                "temperature_domain_c": [temperatures[0], temperatures[-1]], "n_specimens": len(rows),
                "n_dependence_components": len(groups), "exclusions": exclusions,
                "uncertainty_status": "future_specimen_predictive_uncertainty_not_estimated",
                "uncertainty_components": {"conditional_interpolated_mean_se": mean_se, "temperature_cells": summaries,
                    "between_delivery_sd": None, "interpolation_discrepancy_sd": None, "future_individual_predictive_sd": None},
                "limitations": ["Components are assumed comparable; labels do not establish independence",
                    "Mean SE is descriptive, not a prediction interval or probability of material attainment",
                    "Unknown preparation and cycle effects, causal sufficiency and magnetic properties remain unresolved"]}
        predictions.append(output)
    return {"predictions": predictions, "model_version": BASELINE_VERSION,
            "model_origin": "predeclared_conventional_public_evidence_baseline"}


def predictor_source():
    """Standalone numerical-executor source; excludes selector and owner worlds."""
    from pathlib import Path
    return Path(__file__).read_text().split("\ndef predictor_source():", 1)[0]


def study_worlds():
    """Four owner-private coverage conditions, all one exposed mechanism family.

    Names explain the construction to reviewers; no investigator receives names,
    seed, curves, config hashes, expected responses, or this source module.
    """
    from .models.simulation import microstructure_stress_world, synthetic_worlds
    base = microstructure_stress_world()
    revision = copy.deepcopy(base)
    revision["world_id"] = "revision_density_tail_tradeoff"
    retention = copy.deepcopy(base)
    retention.update(world_id="retention_stable_comparable_response",
        density_curve=[[525, 6.6], [550, 6.75], [600, 7.00434], [700, 7.50792], [800, 7.50792], [825, 7.50792]])
    retention["microstructure"].update(
        fine_size_curve_nm=[[550, 60], [600, 75], [650, 100], [700, 130], [800, 190]],
        coarse_size_curve_nm=[[550, 80], [600, 100], [650, 140], [700, 170], [800, 240]],
        coarse_component_weight_curve=[[550, .02], [600, .02], [650, .02], [700, .02], [800, .02]],
        porosity_area_fraction_curve=[[550, .015], [600, .015], [650, .015], [700, .015], [800, .015]])
    ambiguity = copy.deepcopy(base)
    ambiguity.update(world_id="ambiguity_indicated_delivery_bias", temperature_bias_c=12.0,
        temperature_range_c=[525.0, 825.0], density_curve=synthetic_worlds()["density_tradeoff"]["density_curve"])
    # Public requests remain 550..800. Pad owner response support so valid requested
    # endpoints do not become unrelated execution failures after the +12 C readback.
    for container, keys in [(ambiguity, ["density_curve"]), (ambiguity["microstructure"],
            ["fine_size_curve_nm", "coarse_size_curve_nm", "coarse_component_weight_curve", "porosity_area_fraction_curve"])]:
        for key in keys:
            points = container[key]
            container[key] = [[525, points[0][1]], *points, [825, points[-1][1]]]
    nonidentifiable = copy.deepcopy(base)
    nonidentifiable.update(world_id="nonidentifiable_unresolved_grain_boundaries", grain_boundaries_resolved=False)
    return {"revision": revision, "retention": retention, "ambiguity": ambiguity,
            "nonidentifiability": nonidentifiable}


def make_request(temperatures, *, prefix, template, repeats=3):
    """Public conventional action constructor; independent synthetic preparations."""
    request = {"origin": template["origin"], "lot_id": template["lot_id"], "specimens": [],
               "design_origin": "predeclared_conventional_sequential_selector"}
    prototype = template["specimens"][0]
    for index, temperature in enumerate(temperatures):
        for repeat in range(repeats):
            sid = f"{prefix}-{index + 1}-{repeat + 1}"
            specimen = copy.deepcopy(prototype)
            specimen.update(specimen_id=sid, preparation_id="prep-" + sid, cycle_id="cycle-" + sid)
            specimen["conditions"]["temperature_c"] = float(temperature)
            request["specimens"].append(specimen)
    return request


def select_next_request(evidence, history, *, template, max_specimens=24,
                        density_margin_g_cm3=0.05, reference_temperature_c=775.0):
    """Predeclared screen -> density-boundary refinement -> fresh comparison.

    Same public experimental actions as investigators; different policy decisions
    and returned data are the acquisition-policy effect. The synthetic density
    margin is a study decision parameter, not an RPI/material acceptance margin.
    Stopping never claims a calibrated probability or identified mechanism.
    """
    used = sum(len(record.get("request", record).get("specimens", [])) for record in history)
    stage = len(history)
    info = {"version": "conventional-sequential-selection-v1", "action_access": "same-public-action-space",
            "requested_specimens": used, "density_margin_g_cm3": density_margin_g_cm3,
            "margin_scope": "conditional study decision only; not an RPI acceptance limit"}
    if stage == 0:
        temperatures, rationale = [600.0, 700.0, reference_temperature_c], "Screen a lower condition, an intermediate condition and a concurrent reference"
    elif stage >= 3:
        return {**info, "action": "stop", "status": "predeclared_computational_study_allocation_complete",
                "rationale": "Completed screen, refinement and independent candidate/reference comparison; report descriptive evidence and unresolved physical uncertainty separately",
                "decision": terminal_decision(evidence, history[-1].get("request", history[-1]), density_margin_g_cm3=density_margin_g_cm3)}
    else:
        probe_temperatures = [600.0, 625.0, 650.0, 675.0, 700.0, 725.0, 750.0, reference_temperature_c]
        probes = make_request(probe_temperatures, prefix="selector-probe", template=template, repeats=1)
        predictions = forecast({"request": probes, "evidence": evidence})["predictions"]
        density = {t: p.get("density_g_cm3", {}).get("mean") for t, p in zip(probe_temperatures, predictions, strict=True)}
        reference = density[reference_temperature_c]
        if reference is None:
            return {**info, "action": "stop", "status": "measurement_or_applicability_unresolved",
                    "rationale": "No eligible numeric reference; require measurement/context review before further manufacture"}
        candidates = [t for t in probe_temperatures[:-1] if density[t] is not None and reference - density[t] <= density_margin_g_cm3]
        candidate = min(candidates) if candidates else 750.0
        if stage == 2:
            previous = history[-1].get("request", history[-1])
            candidate = min(s["conditions"]["temperature_c"] for s in previous["specimens"])
        temperatures = [candidate, reference_temperature_c]
        rationale = "Explore the lowest interpolated density-compatible candidate and a concurrent reference" if stage == 1 else "Fresh independent preparation/cycle confirmation of the selected candidate and reference; inspect full microstructure before any tradeoff claim"
    count = 3 * len(temperatures)
    if used + count > max_specimens:
        return {**info, "action": "stop", "status": "resource_censored", "rationale": "Remaining specimen allowance cannot fund the declared comparison"}
    request = make_request(temperatures, prefix=f"conventional-{stage + 1}", template=template)
    return {**info, "action": "request_experiment", "rationale": rationale, "request": request,
            "request_sha256": hashlib.sha256(json.dumps(request, sort_keys=True, separators=(",", ":")).encode()).hexdigest()}


def study_request_template():
    """Common public measurement context and recipe for all conditional cases."""
    from .models.coverage import coverage_source_packet
    from .workflow import example_request
    request = example_request()
    measurements = ["density_g_cm3", "grain_size_nm", "sps_log", "microstructure",
                    "grain_d90_nm", "coarse_number_fraction", "porosity_area_fraction"]
    context = coverage_source_packet()["scientific_tools"]["measurement_context"]
    for specimen in request["specimens"]:
        specimen["conditions"].update(process_stage="initial_sps", die_material="graphite",
                                       measurement_context=copy.deepcopy(context))
        specimen["measurements"] = list(measurements)
    return request


def fixed_target_request(*, prefix="private-fixed-target", lot_id="synthetic-melt-spun-lot"):
    """Owner-private untouched target panel, not investigator acquisition actions."""
    template = study_request_template()
    template["lot_id"] = lot_id
    return make_request([575.0, 625.0, 675.0, 725.0, 775.0], prefix=prefix,
                        template=template, repeats=3)


def terminal_decision(evidence, confirmation_request, *, density_margin_g_cm3=0.05,
                      porosity_margin=0.002):
    """Separate fresh achieved proxy contrasts; no confidence or composite reward.

    Margins are declared synthetic-study decision parameters, not RPI acceptance
    criteria. Only specimens in the fresh confirmation request enter this record.
    """
    by_temperature = defaultdict(set)
    for specimen in confirmation_request["specimens"]:
        by_temperature[specimen["conditions"]["temperature_c"]].add(specimen["specimen_id"])
    temperatures = sorted(by_temperature)
    if len(temperatures) != 2:
        return {"status": "not_assessable", "reason": "Requires a candidate and concurrent reference"}
    candidate, reference = temperatures
    condition = confirmation_request["specimens"][0]["conditions"]
    comparisons = {}
    for quantity, unit in _UNITS.items():
        rows, excluded = _eligible(condition, confirmation_request, evidence, quantity)
        summaries = {}
        for temperature, identifiers in by_temperature.items():
            subset = [row for row in rows if row["specimen_id"] in identifiers]
            groups = _components(subset)
            values = [sum(r["value"] for r in group) / len(group) for group in groups]
            summaries[temperature] = {"mean": sum(values) / len(values) if values else None,
                "n_specimens": len(subset), "n_components": len(groups),
                "evidence_ids": [row["evidence_id"] for row in subset],
                "actual_temperature_range_c": [min(r["delivered_conditions"]["temperature_c"] for r in subset),
                    max(r["delivered_conditions"]["temperature_c"] for r in subset)] if subset else None}
        left, right = summaries[candidate]["mean"], summaries[reference]["mean"]
        delta = left - right if left is not None and right is not None else None
        if quantity == "density_g_cm3":
            criterion, descriptive = "candidate-reference >= -density_margin", delta >= -density_margin_g_cm3 if delta is not None else None
        elif quantity == "porosity_area_fraction":
            criterion, descriptive = "candidate-reference <= porosity_margin", delta <= porosity_margin if delta is not None else None
        else:
            criterion, descriptive = "candidate-reference <= 0", delta <= 0 if delta is not None else None
        comparisons[quantity] = {"candidate": summaries[candidate], "reference": summaries[reference],
            "candidate_minus_reference": delta, "unit": unit, "criterion": criterion,
            "descriptive_criterion_met": descriptive, "exclusions": excluded}
    verdicts = [item["descriptive_criterion_met"] for item in comparisons.values()]
    status = "descriptive_tradeoff_or_constraint_failure" if False in verdicts else (
        "unresolved_joint_tradeoff" if None in verdicts else "qualified_candidate_for_further_verification")
    return {"status": status, "comparisons": comparisons,
        "density_margin_g_cm3": density_margin_g_cm3, "porosity_margin": porosity_margin,
        "margin_scope": "Predeclared conditional-study proxy criteria; no magnetic, physical or economic acceptance claim",
        "uncertainty": "No identified future-delivery uncertainty or probability of meeting criteria; near-threshold classifications remain descriptive",
        "causal_scope": "Achieved condition groups; requested temperature alone is not identified as cause",
        "material_status": "physical_evidence_pending; no material validation",
        "stopping_scope": "Conventional computational allocation complete; unresolved apparatus, boundary chemistry, texture and magnetic outcomes remain open"}


def blind_study_delivery(delivery):
    """Remove owner generator internals while preserving labeled synthetic evidence.

    Native execution and replay receipts retain the original private delivery.
    This public copy keeps all numerical values, arrays, observations, identities,
    quality state, genealogy, measurement semantics and nonphysical provenance.
    """
    public = copy.deepcopy(delivery)
    public["provenance"] = {
        "evidence_class": "conditional_synthetic",
        "model_version": "blinded-conditional-study-export-v1",
        "physical_execution": False,
        "export_status": "public_measurement_export_private_generator_context_excluded",
    }
    for row in public.get("observations", []):
        if row.get("quantity") == "sps_log" and isinstance(row.get("value"), dict):
            row["value"].pop("model", None)
            row["value"]["temperature_meaning"] = "indicated_temperature; not a direct measurement of the full internal temperature field"
        elif row.get("quantity") == "microstructure" and isinstance(row.get("value"), dict):
            row["value"].pop("porosity_model", None)
            row["value"]["limits"] = [
                "Conditional computational observations, not RPI calibration",
                "Feature/field sampling does not determine uncertainty in a future delivery",
                "2D section porosity is not bulk void fraction",
                "Distribution morphology and chemistry cannot establish magnetic performance",
            ]
    return public
